customTools.schemaSource:
z.object({
  csv: z.string().describe("CSV text with a header row"),
  delimiter: z.string().length(1).default(",").describe("Field separator"),
})

customTools.code:
const lines = input.csv.trim().split(/\r?\n/).filter((l) => l.length);
if (lines.length < 2) throw new Error("Need a header row and at least one data row.");
const split = (line) => line.split(input.delimiter).map((c) => c.trim());
const columns = split(lines[0]);
const rows = lines.slice(1).map(split);
const numeric = {};
columns.forEach((name, i) => {
  const values = rows.map((r) => Number(r[i])).filter((v) => Number.isFinite(v));
  if (values.length === rows.length) {
    const sum = values.reduce((a, b) => a + b, 0);
    numeric[name] = { min: Math.min(...values), max: Math.max(...values), mean: +(sum / values.length).toFixed(4) };
  }
});
return { rows: rows.length, columns, numeric };
